using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Measurement.Pgm;
internal sealed class EquiprobablePgmComparisonDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Quantum/Measurement/Pgm/EquiprobablePgmComparison.";
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual symmetric CFC scores and active-set failure", H("Actual symmetric CFC scores and active-set failure"), Blocks(
            Node("inverse_sqrt_two", "Two-coordinate spectral inverse square root", DescribeRole.Theorem, "The inverse square root of diag(u,v), for arbitrary nonnegative u,v including zero, is diag(sqrt(u)^(-1),sqrt(v)^(-1)). This shared CFC evaluation helper is consumed by the actual score and effect calculations; it assumes no invertibility.", "mazhang2026pgmratio"),
            Node("symmetric_scores", "Both actual symmetric scores", DescribeRole.Theorem, "For every real a,b,c with 0<a,c<1, the actual original-prior restricted and full CFC scores of rho(a,b,c) satisfy P_{0,1}-1/3=2b^2/(3sqrt(a(1-a))) and P_all-1/3=4b^2/(3sqrt(D))+2(c-a)^2/(3D), D=(2a+c)(3-2a-c). The evaluation does not need a pair determinant hypothesis. When b^2<=a(1-a), the pair is physical, including the singular equality case; strict determinant positivity gives the full strict-PD setting. The proof evaluates the existing diagonal CFC, including its support inverse, and multiplies the actual matrices inside the existing score definition. Hyunho Cha is credited for these symmetric calculations.", "mazhang2026pgmratio"),
            Node("pair_failure_iff", "The strict score criterion", DescribeRole.Theorem, "For every 0<a,c<1, the actual pair/full score inequality 2(P_all-1/3)<P_{0,1}-1/3 holds if and only if D>16q and b^2>2(c-a)^2sqrt(q)/(sqrt(D)(sqrt(D)-4sqrt(q))), with q=a(1-a), D=(2a+c)(3-2a-c). Either equality is nonfailure. The actual CFC scores are bound through symmetric_scores; no evaluation bridge is assumed. This scalar-equivalent test concerns the pair label set; the full optimizer theorem additionally needs that set to be active.", "mazhang2026pgmratio"),
            Node("active_failure_iff", "The actual active-set failure iff", DescribeRole.Theorem, "For every 0<a,c<1, b>0 and b^2<a(1-a), all three actual rho_i are PD trace-one states. With A the nonzero effects of the actual optimalPovm, the original strict failure (|A|-1)(P_A-1/3)>2(P_all-1/3) holds if and only if |c-a|<=b AND D>16q AND b^2>2(c-a)^2sqrt(q)/(sqrt(D)(sqrt(D)-4sqrt(q))). The pair-region conjunct is essential. With three active labels the comparison is equality. This binds the strict criterion to the exact optimizer and its active labels, over the complete strict physical domain.", "mazhang2026pgmratio"),
            Node("sqrt_inverse_square", "sqrt_inverse_square", DescribeRole.Theorem, "For every u>=0, (sqrt(u)^(-1))^2=u^(-1), including u=0. This algebra helper is consumed by the actual symmetric CFC scores.", null),
            Node("sqrt_inverse_product", "sqrt_inverse_product", DescribeRole.Theorem, "For u>=0 and any real v, sqrt(u)^(-1)sqrt(v)^(-1)=sqrt(uv)^(-1). This CFC-evaluation algebra helper is consumed by the actual symmetric score calculation.", null),
            Node("inverse_sqrt_residual", "Shared rationalized inverse-square-root residual", DescribeRole.Theorem, "For every real u with 1-u>0, 1/sqrt(1-u)-1=u/[sqrt(1-u)(1+sqrt(1-u))]. This algebra helper is consumed by the actual qubit and loading asymptotic estimates.", null),
            Paragraph(Text("Source custody: the mechanism manuscript is anonymous (3 November 2026); no license grant was supplied. The old literal byline remains Wenlin Zhang and Haobo / trureturing, and its actual rational proof is reused as EquiprobablePgmActiveSetRefutation.result. The new note is by Haobo Ma then Wenlin Zhang (4 November 2026), with CC BY 4.0 restricted to that new note. Hyunho Cha is credited for the symmetric scores and qubit/commuting constructions. The metadata URLs locate immutable repository citation records, not public manuscript originals. Activity means a nonzero effect, including rank-one effects; the source wording about positive definite effects is ambiguous. General all-pure and positive-spectral-floor comparisons remain open. No priority or publication claim is made."))
        ), []));
    private static DocumentBlock Node(string name, string title, DescribeRole role, string prose, string? note) => Describe.Lean(
        DescribeId.Create("pgm-comparison-" + name.Replace('_', '-').ToLowerInvariant()),
        DeclarationHandle.Create(Prefix + name), H(title), StatementSource.WithoutFormula(),
        note is null ? AssessedProvenance.FromRepo() : AssessedProvenance.FromLiterature(LibraryNoteRef.Create("D5/L/Estimation/" + note)),
        Blocks(Paragraph(Text(prose))), role);
}
